class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        import heapq
        heap = []                        # 小顶堆，最多 k 个
        for x in nums:
            heapq.heappush(heap, x)
            if len(heap) > k:
                heapq.heappop(heap)      # 弹掉最小的
        return heap[0]                   # 堆顶 = 第 k 大

class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        import heapq
        from collections import Counter
        cnt = Counter(nums)                       # ① 统计频次
        heap = []                                 # ② 小顶堆按频次保 k 个
        for num, c in cnt.items():
            heapq.heappush(heap, (c, num))
            if len(heap) > k:
                heapq.heappop(heap)
        return [num for c, num in heap]           # ③ 收集

class MedianFinder:
    def __init__(self):
        import heapq
        self.left = []    # 大顶堆（存负数模拟）：较小的一半
        self.right = []   # 小顶堆：较大的一半

    def addNum(self, num: int) -> None:
        import heapq
        heapq.heappush(self.left, -num)             # ① 先进左堆
        heapq.heappush(self.right, -heapq.heappop(self.left))  # ② 左堆最大给右堆
        if len(self.right) > len(self.left):        # ③ 右堆过长则挪回
            heapq.heappush(self.left, -heapq.heappop(self.right))

    def findMedian(self) -> float:
        import heapq
        if len(self.left) > len(self.right):
            return float(-self.left[0])
        return (-self.left[0] + self.right[0]) / 2
